message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a small patch of bare ground. Its overall body shape, posture, and dense shaggy fur resemble a brown bear, with a robust torso, thick neck, and four sturdy legs ending in clawed paws. The fur is dark to medium brown over most of the back, sides, head and legs, with a lighter cream-tan color on the lower chest, belly and muzzle. The head is bear-like with a black nose and small dark eyes. Behind the head on the upper back and neck sits a large glossy dark brown-black curved structure that arches forward over the head. Along the lower sides of the body, on the hindquarters, and on the upper forelegs are rows of narrow vertical oval openings with dotted perforated interiors set into the fur. Small glossy dark plates are visible at the leg joints and near the paws and at the base of the large curved structure on the back.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a lighter tan muzzle, a large black nose with nostrils, a closed mouth, and a small dark brown eye visible in profile",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "a single large glossy dark brown to black smooth horn, strongly curved forward with a pointed forked tip and a smaller tooth-like projection on its inner curve, arising from a broad oval glossy plate",
      "where": "on the dorsal midline of the upper back and neck directly behind and over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in short brown fur with slightly lighter edges",
      "where": "on top of the head, one on each side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in long shaggy brown fur, with slightly lighter fur on the inner sides",
      "where": "two forelegs under the chest and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark curved claws on the toes and furry tops, the soles not visible",
      "where": "at the bottom ends of the four legs on the ground"
    },
    {
      "part": "gills",
      "looks_like": "rows of narrow vertical oval slits with a pale interior covered in small dark dots, resembling spiracles or gill slits, about seven along the mid-flank, four on the hindquarter, and four on the shoulder of the foreleg, plus a few small round dotted pits on the lower belly",
      "where": "set into the fur along the lower side of the torso, the hindquarter, the lower belly, and the upper foreleg"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark brown-black chitinous plates with smooth reflective surfaces, including a large oval plate at the base of the horn and smaller curved crescent plates",
      "where": "the large plate on the upper back under the horn, and smaller plates wrapping around the joints of all four legs and near the front and hind paws"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy brown fur that is darker on the back and legs and grades to a pale cream-beige on the chest and belly, with no spots or stripes other than the rows of gill slits and dark plates",
      "where": "over the entire body"
    },
    {
      "part": "tail",
      "looks_like": "no distinct tail is visible; the rear is rounded and covered in fur",
      "where": "at the rear of the body where a tail would be"
    }
  ],
  "attached_objects": [],
  "animals": ["brown bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 0
}
